/**
 * The company logo (Leap Auto Parts, round gold) in every place that needs it:
 *   brand/leap-logo.png (master copy) and brand/leap-logo-original.png (as given),
 *   the admin, supplier and inspection hub portals (public/brand/leap-logo.png: they show it at the top, see patch-portal-brand),
 *   the website (apps/web-storefront/public/brand/) and the mobile app (apps/mobile/assets/brand/), ready to use there.
 * Also gives the logo in the portals a round shape with a thin white ring, so it stays clear on the gold admin menu.
 * Needs patch-portal-brand first.
 *
 *   node scripts/patch-logo-files.js            dry run
 *   node scripts/patch-logo-files.js --write    applies it (each changed code file is saved as <file>.before-logo-files first)
 */
const fs = require('fs'); const path = require('path');
const FILES = [["brand/leap-logo.png", "", "master copy (1024 px, transparent corners)"], ["brand/leap-logo-original.png", "", "the logo as it was given"], ["apps/admin-dashboard/public/brand/leap-logo.png", "", "admin portal"], ["apps/supplier-portal/public/brand/leap-logo.png", "", "supplier portal"], ["apps/hub-portal/public/brand/leap-logo.png", "", "inspection hub portal"], ["apps/web-storefront/public/brand/leap-logo.png", "", "website (ready to use)"], ["apps/mobile/assets/brand/leap-logo.png", "", "mobile app (ready to use)"]];
const EDITS = [["apps/admin-dashboard/src/components/PageChrome.jsx", "style={{ width: size, height: size, objectFit: \"contain\", borderRadius: 10, flexShrink: 0, display: \"block\" }} />;", "style={{ width: size, height: size, objectFit: \"contain\", borderRadius: \"50%\", flexShrink: 0, display: \"block\", boxShadow: \"0 0 0 2px rgba(255, 255, 255, 0.85)\" }} />;      // a thin white ring: the round gold logo stays clear on the gold menu"], ["apps/supplier-portal/src/components/PageChrome.jsx", "style={{ width: size, height: size, objectFit: \"contain\", borderRadius: 10, flexShrink: 0, display: \"block\" }} />;", "style={{ width: size, height: size, objectFit: \"contain\", borderRadius: \"50%\", flexShrink: 0, display: \"block\", boxShadow: \"0 0 0 2px rgba(255, 255, 255, 0.85)\" }} />;      // a thin white ring: the round gold logo stays clear on the gold menu"], ["apps/hub-portal/src/App.jsx", "style={{ width: size, height: size, objectFit: \"contain\", borderRadius: 10, flexShrink: 0, display: \"block\" }} />;", "style={{ width: size, height: size, objectFit: \"contain\", borderRadius: \"50%\", flexShrink: 0, display: \"block\", boxShadow: \"0 0 0 2px rgba(255, 255, 255, 0.85)\" }} />;      // a thin white ring: the round gold logo stays clear on the gold menu"]];
const root = path.resolve(__dirname, '..'); const write = process.argv.includes('--write');
let problems = 0; const plan = [];
for (const [rel, data, what] of FILES) {
  const p = path.join(root, rel); const buf = Buffer.from(data, 'base64');
  if (fs.existsSync(p) && fs.readFileSync(p).equals(buf)) { console.log('already   ' + rel + ': ' + what); continue; }
  console.log((write ? 'writing   ' : 'would add ') + rel + ': ' + what + ' (' + Math.round(buf.length / 1024) + ' KB)');
  plan.push(() => { fs.mkdirSync(path.dirname(p), { recursive: true }); fs.writeFileSync(p, buf); });
}
for (const [rel, oldText, newText] of EDITS) {
  const p = path.join(root, rel);
  if (!fs.existsSync(p)) { console.log('MISSING   ' + rel); problems++; continue; }
  let s = fs.readFileSync(p, 'utf8'); const crlf = s.includes('\r\n'); if (crlf) s = s.replace(/\r\n/g, '\n');
  if (s.includes(newText)) { console.log('already   ' + rel + ': round logo with a white ring'); continue; }
  if (s.split(oldText).length !== 2) { console.log('REFUSED   ' + rel + ': the logo code is not where expected (apply patch-portal-brand first)'); problems++; continue; }
  console.log((write ? 'changing  ' : 'would     ') + rel + ': round logo with a white ring');
  plan.push(() => { const raw = fs.readFileSync(p, 'utf8'); fs.writeFileSync(p + '.before-logo-files', raw); let out = s.replace(oldText, () => newText); if (crlf) out = out.replace(/\n/g, '\r\n'); fs.writeFileSync(p, out); });
}
if (problems) { console.log('\nNothing was changed: fix the lines marked above first.'); process.exit(1); }
if (!write) { console.log('\nDry run only. Add --write to apply.'); process.exit(0); }
plan.forEach((f) => f());
if (plan.length) console.log('\nDone. Refresh the admin, supplier and hub portals (Ctrl+F5); the portals show the logo straight away.');
